input.command:
cp src/main_window.rs /tmp/mw_pre.rs && python3 - <<'EOF'
p='src/main_window.rs'; s=open(p).read()
anchor="    /// Clicking a file in the project tree opens it beside the chat history,"
t='''    #[gpui_kit::test]
    async fn zz_seam(cx: &mut TestAppContext) {
        use gpui_kit::component::{Theme, ThemeMode};
        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::theme::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
        });
        let mut main = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| MainWindow::new(window, cx));
            main = Some(view.clone());
            Root::new(view, window, cx)
        });
        let handle = window.into();
        let ribbon = main.unwrap().read_with(cx, |main, _| main.ribbon.clone());
        for (name, tab) in [("project", crate::ribbon::RibbonTab::Project), ("code", crate::ribbon::RibbonTab::Code)] {
            ribbon.update(cx, |r, cx| r.tab_clicked(tab, 1, false, cx));
            for mode in [ThemeMode::Dark, ThemeMode::Light] {
                cx.update(|cx| Theme::change(mode, None, cx));
                cx.run_until_parked();
                cx.update_window(handle, |_, window, cx| {
                    window.render_frame(cx);
                    window.simulate_mouse_move(gpui_kit::point(gpui_kit::px(900.), gpui_kit::px(600.)), cx);
                    window.render_frame(cx);
                    crate::frame_image::save(window, std::path::Path::new(&format!("/tmp/seam-{name}-{mode:?}.ppm")));
                    for q in window.painted_quads().iter().filter(|q| q.bounds.origin.y.0 < 90. && q.bounds.origin.y.0 + q.bounds.size.height.0 > 50. && q.bounds.origin.y.0 + q.bounds.size.height.0 < 90.) {
                        let m = &q.content_mask.bounds;
                        eprintln!("{name} {mode:?} Q [{},{} {}x{}] bw t{} b{} bg {:?} bc a{:.2} mask [{},{} {}x{}]", q.bounds.origin.x.0, q.bounds.origin.y.0, q.bounds.size.width.0, q.bounds.size.height.0, q.border_widths.top.0, q.border_widths.bottom.0, q.background.as_solid().map(|c| (c.l, c.a)), q.border_color.a, m.origin.x.0, m.origin.y.0, m.size.width.0, m.size.height.0);
                    }
                }).unwrap();
            }
        }
    }

'''
s=s.replace(anchor,t+anchor,1); open(p,'w').write(s)
EOF
cargo test zz_seam -- --nocapture 2>&1 | grep -E "^error|Q \[" | head -40; cp /tmp/mw_pre.rs src/main_window.rs; cd /tmp && for f in seam-project-Dark seam-code-Dark seam-project-Light; do echo "== $f"; for y in 56 58 60 61 62 63 64 65 66 68; do printf "y=$y x350:%s x2000:%s x100:%s\n" "$(magick $f.ppm -format '%[pixel:p{350,'$y'}]' info:)" "$(magick $f.ppm -format '%[pixel:p{2000,'$y'}]' info:)" "$(magick $f.ppm -format '%[pixel:p{100,'$y'}]' info:)"; done; done

