p='src/ribbon/mod.rs'; s=open(p).read()
a="""/// The height of the row of tabs: gpui-kit's tab bar, less the line along its
/// bottom.
const TAB_ROW_HEIGHT: Pixels = px(31.);"""
b="""/// The height of the row of tabs: gpui-kit's tab bar, less the line along its
/// bottom and a pixel more, so that at a fractional display scale, where the
/// clip falls between device pixels, no softened edge of that line shows as a
/// faint seam between the tabs and the commands beneath them.
const TAB_ROW_HEIGHT: Pixels = px(30.);"""
assert a in s; open(p,'w').write(s.replace(a,b))
EOF
